module tb_TopModule;
    logic       in;
    logic [3:0] state;
    logic [3:0] next_state;
    logic       out;

    TopModule uut (
        .in(in),
        .state(state),
        .next_state(next_state),
        .out(out)
    );

    initial begin
        integer s, i;
        logic [3:0] exp_ns;
        logic       exp_out;

        // Test all states and inputs
        for (s = 0; s < 4; s = s + 1) begin
            for (i = 0; i < 2; i = i + 1) begin
                state = (1 << s);
                in = i[0];
                #1;

                // Expected values based on specification table:
                // State A (0001): in=0 -> A (0001), in=1 -> B (0010). out=0
                // State B (0010): in=0 -> C (0100), in=1 -> B (0010). out=0
                // State C (0100): in=0 -> A (0001), in=1 -> D (1000). out=0
                // State D (1000): in=0 -> C (0100), in=1 -> B (0010). out=1

                case (s)
                    0: begin // A
                        exp_ns = (i == 0) ? 4'b0001 : 4'b0010;
                        exp_out = 1'b0;
                    end
                    1: begin // B
                        exp_ns = (i == 0) ? 4'b0100 : 4'b0010;
                        exp_out = 1'b0;
                    end
                    2: begin // C
                        exp_ns = (i == 0) ? 4'b0001 : 4'b1000;
                        exp_out = 1'b0;
                    end
                    3: begin // D
                        exp_ns = (i == 0) ? 4'b0100 : 4'b0010;
                        exp_out = 1'b1;
                    end
                endcase

                if (next_state !== exp_ns || out !== exp_out) begin
                    $display("SELFTEST FAIL: state=%b, in=%b -> next_state=%b (exp %b), out=%b (exp %b)",
                             state, in, next_state, exp_ns, out, exp_out);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
